competency.sparql:
SELECT ?project ?grant_number ?mechanism WHERE {
  ?project a bbqs:Project ; bbqs:grant_number ?grant_number .
  OPTIONAL { ?project bbqs:mechanism ?mechanism }
} ORDER BY ?grant_number

SELECT ?mechanism (COUNT(?project) AS ?projects) (SUM(?amount) AS ?total) WHERE {
  ?project a bbqs:Project ; bbqs:mechanism ?mechanism ; bbqs:award_amount ?amount .
} GROUP BY ?mechanism ORDER BY DESC(?total)

SELECT ?project ?grant_number ?org_name WHERE {
  ?project a bbqs:Project ; bbqs:grant_number ?grant_number ; bbqs:part_of_org ?org .
  ?org bbqs:name ?org_name .
}

SELECT ?name ?role WHERE {
  ?project bbqs:grant_number "R34DA059723" .
  ?pr a bbqs:ProjectRole ; bbqs:on_project ?project ; bbqs:project_role ?role ;
      bbqs:held_by ?person .
  ?person bbqs:name ?name .
}

SELECT ?name (COUNT(DISTINCT ?project) AS ?projects) WHERE {
  ?pr a bbqs:ProjectRole ; bbqs:held_by ?person ; bbqs:on_project ?project .
  ?person bbqs:name ?name .
} GROUP BY ?person ?name HAVING (COUNT(DISTINCT ?project) > 1) ORDER BY DESC(?projects)

SELECT ?name ?org_name WHERE {
  ?org a bbqs:ResearchOrganization ; bbqs:name ?org_name ; bbqs:members ?person .
  ?person a bbqs:Investigator ; bbqs:name ?name .
}

SELECT ?name ?orcid WHERE {
  ?person a bbqs:Investigator ; bbqs:name ?name ; bbqs:orcid ?orcid .
}

SELECT ?name WHERE {
  ?wg a bbqs:WorkingGroup ; bbqs:name "WG-Devices" .
  ?person bbqs:member_of_group ?wg ; bbqs:name ?name .
}

SELECT ?project ?grant_number WHERE {
  ?species a bbqs:Species ; bbqs:common_name "House Mouse" .
  ?project bbqs:studies_species ?species ; bbqs:grant_number ?grant_number .
}

SELECT DISTINCT ?project ?grant_number WHERE {
  ?species a bbqs:Species ; bbqs:taxonomy_class "Mammalia" .
  ?project bbqs:studies_species ?species ; bbqs:grant_number ?grant_number .
}

SELECT ?project ?grant_number ?scope WHERE {
  ?project a bbqs:Project ; bbqs:grant_number ?grant_number .
  FILTER NOT EXISTS { ?project bbqs:studies_species ?s }
  OPTIONAL { ?project bbqs:study_scope ?scope }
}

SELECT ?grant_number ?title WHERE {
  ?project a bbqs:Project ; bbqs:grant_number ?grant_number ; bbqs:produced ?pub .
  ?pub a bbqs:Publication ; bbqs:title ?title .
}

SELECT ?grant_number ?dataset_name WHERE {
  ?project a bbqs:Project ; bbqs:grant_number ?grant_number ;
           (bbqs:funded_datasets|bbqs:produced) ?dataset .
  ?dataset a bbqs:Dataset ; bbqs:name ?dataset_name .
}

SELECT ?grant_number ?category WHERE {
  ?project a bbqs:Project ; bbqs:grant_number ?grant_number ; bbqs:uses_device_category ?cat .
  ?cat bbqs:label ?category .
}

SELECT ?manufacturer ?model ?category WHERE {
  ?device a bbqs:Device ; bbqs:model_name ?model ; bbqs:manufacturer ?m .
  ?m bbqs:name ?manufacturer .
  OPTIONAL { ?device bbqs:device_category ?category }
}

SELECT ?name ?repo WHERE {
  ?tool a bbqs:SoftwareTool ; bbqs:name ?name ; bbqs:repo_url ?repo .
}

SELECT ?title ?expires WHERE {
  ?fo a bbqs:FundingOpportunity ; bbqs:name ?title ; bbqs:expiration_date ?expires .
  FILTER (?expires > "2026-09-29"^^xsd:date)
}

SELECT ?title ?institution WHERE {
  ?job a bbqs:Job ; bbqs:name ?title ; bbqs:job_institution ?institution .
}

SELECT ?value ?source ?grade WHERE {
  ?project bbqs:grant_number "R34DA059723" .
  BIND(STRAFTER(STR(?project), "https://brain-bbqs.org/id/") AS ?localId)
  ?prov a bbqs:ProvenanceRecord ; bbqs:prov_entity_id ?localId ;
        bbqs:prov_entity_column "title" ; bbqs:prov_value_text ?value ;
        bbqs:prov_source_class ?source .
  OPTIONAL { ?source bbqs:grade ?grade }
}
